public class OperatorHierarchy {
    public static void main(String[] args) {
        int a = 4;
        int b = 7;
        int c = 2;
        int d = a = b - c * 2;

        if (a + c > b == b / a > c) {
            a = a + 10;
        }
        if (d <= a != b >= a) {
            d = d + 20;
        }
        System.out.printf("a=%d, d=%d", a, d);
    }
}

public class FinalChallenge {
    public static void main(String[] args) {
        int m = 14;
        int n = 4;
        int p = m % n + m / n;

        if (p * n >= m)
            p = p + n;
        if (m - p == n); {
            p = p * 2;
        }
        System.out.printf("p=%d, m=%d\rp=%d", n, m, p);
    }
}
